// collect.mjs — reproduce the observed capability-string corpus for the
// BasedAgents capability-taxonomy task (task_8tsVQ5tpc7AykJ4Hrbj7l).
// Sources (all public, read-only):
//   1. BasedAgents API: agent profiles (capabilities, skills, tags) via
//      /v1/agents/search pagination; task required_capabilities via /v1/tasks
//      (open) and /v1/tasks/settled.
//   2. A2A samples (github a2aproject/a2a-samples): agent-card skills[].id + tags.
//   3. Coinbase AgentKit (github coinbase/agentkit): action_providers names.
//   4. crewAI-tools (github crewAIInc/crewAI-tools): tool directory names.
// Output: corpus.json — [{capability_string, count, sources:[{registry, field}]}]
// Usage: node collect.mjs > corpus.json
const BA = 'https://api.basedagents.ai';
const seen = new Map();
function add(str, registry, field) {
  if (typeof str !== 'string') return;
  const s = str.trim();
  if (!s) return;
  const key = s.toLowerCase();
  if (!seen.has(key)) seen.set(key, { capability_string: s, count: 0, sources: [] });
  const e = seen.get(key);
  e.count++;
  if (!e.sources.some(x => x.registry === registry && x.field === field)) e.sources.push({ registry, field });
}
async function j(url) { const r = await fetch(url); if (!r.ok) throw new Error(url + ' -> ' + r.status); return r.json(); }

// 1a. BasedAgents agents (paginated census)
const first = await j(`${BA}/v1/agents/search?limit=200&page=1`);
const pages = first.pagination?.total_pages ?? 1;
const ingestAgents = (agents) => { for (const a of agents) {
  for (const c of a.capabilities || []) add(c, 'basedagents', 'agent.capabilities');
  for (const c of a.skills || []) add(c, 'basedagents', 'agent.skills');
  for (const c of a.tags || []) add(c, 'basedagents', 'agent.tags');
}};
ingestAgents(first.agents || []);
for (let p = 2; p <= pages; p++) { const d = await j(`${BA}/v1/agents/search?limit=200&page=${p}`); ingestAgents(d.agents || []); }
// 1b. BasedAgents tasks
for (const url of [`${BA}/v1/tasks?status=open`, `${BA}/v1/tasks/settled`]) {
  try { const d = await j(url); const tasks = d.tasks || d.settled || [];
    for (const t of tasks) for (const c of t.required_capabilities || []) add(c, 'basedagents', 'task.required_capabilities');
  } catch { /* settled endpoint optional */ }
}
// 2. A2A agent cards
const a2aTree = await j('https://api.github.com/repos/a2aproject/a2a-samples/git/trees/main?recursive=1');
const cardPaths = a2aTree.tree.filter(t => /agent_cards?\/[^/]+\.json$|agent_card\.json$/.test(t.path)).map(t => t.path);
for (const p of cardPaths) {
  try { const card = await j(`https://raw.githubusercontent.com/a2aproject/a2a-samples/main/${p}`);
    for (const sk of card.skills || []) { if (sk.id) add(sk.id, 'a2a-samples', 'skill.id'); for (const tg of sk.tags || []) add(tg, 'a2a-samples', 'skill.tags'); }
  } catch { /* skip unreadable card */ }
}
// 3. AgentKit action providers
const akTree = await j('https://api.github.com/repos/coinbase/agentkit/git/trees/main?recursive=1');
const providers = new Set();
for (const t of akTree.tree) { const m = t.path.match(/action_providers\/([a-z0-9_]+)\//i); if (m) providers.add(m[1]); }
for (const p of providers) add(p, 'agentkit', 'action_provider');
// 4. crewAI tools
const crewTree = await j('https://api.github.com/repos/crewAIInc/crewAI-tools/git/trees/main?recursive=1');
const tools = new Set();
for (const t of crewTree.tree) { const m = t.path.match(/crewai_tools\/tools\/([a-z0-9_]+)\//i); if (m) tools.add(m[1]); }
for (const p of tools) add(p, 'crewai-tools', 'tool_dir');
console.log(JSON.stringify([...seen.values()].sort((a, b) => b.count - a.count), null, 1));
